import{_ as s,o as t,c as e,ag as i}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-11-04（物理 · 单个碳原子 3D 成像 / 学习智能体记忆中涌现时空）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-11-04-physics.md","filePath":"topics/physics/science-daily-2026-11-04-physics.md"}'),r={name:"topics/physics/science-daily-2026-11-04-physics.md"};function n(c,o,l,d,a,g){return t(),e("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-11-04-物理-·-单个碳原子-3d-成像-学习智能体记忆中涌现时空" tabindex="-1">科学日报 · 2026-11-04（物理 · 单个碳原子 3D 成像 / 学习智能体记忆中涌现时空） <a class="header-anchor" href="#科学日报-·-2026-11-04-物理-·-单个碳原子-3d-成像-学习智能体记忆中涌现时空" aria-label="Permalink to &quot;科学日报 · 2026-11-04（物理 · 单个碳原子 3D 成像 / 学习智能体记忆中涌现时空）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-04.md</code> — 第54期 ｜ 科学板块（物理向 2 篇） 落盘说明：文件名带 <code>-physics</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-04-物理-·-1-2-叠层原子电子断层成像-把「单个轻原子」的三维位置定到-0-12-a" tabindex="-1">科学日报 2026-11-04（物理 · 1/2）：叠层原子电子断层成像，把「单个轻原子」的三维位置定到 0.12 Å <a class="header-anchor" href="#科学日报-2026-11-04-物理-·-1-2-叠层原子电子断层成像-把「单个轻原子」的三维位置定到-0-12-a" aria-label="Permalink to &quot;科学日报 2026-11-04（物理 · 1/2）：叠层原子电子断层成像，把「单个轻原子」的三维位置定到 0.12 Å&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-04.md</code> ｜ DOI: 10.1038/s41565-026-02316-9 ｜ Nature Nanotechnology (2026)</p></blockquote><ul><li>问题：<strong>叠层电子显微（ptychography）<strong>把相干衍射与迭代相位恢复结合，横向分辨率已达</strong>深亚埃</strong>，但<strong>深度分辨率通常仍在纳米级</strong>；<strong>叠层原子电子断层成像（pAET）<strong>能定三维原子结构，却</strong>难以可靠分辨轻原子（如碳）</strong>。</li><li>方法：以<strong>扭转双层石墨烯</strong>为模型<strong>莫尔体系</strong>，用 <strong>pAET</strong> 做三维原子定位；再用<strong>基于实验结构的 DFT</strong> 与 <strong>multislice pAET 模拟</strong>交叉验证并外推到其它材料。</li><li>结果（实测）： <ul><li>三维定位 <strong>6,648 个碳原子、精度 0.12 Å</strong>；</li><li>重建结构揭示<strong>依赖堆叠的层间距与起伏</strong>，以及带 <strong>meron 型 / 反 meron 型 / 反斯格明子型织构</strong>的<strong>手性晶格畸变</strong>；</li><li>DFT 预测<strong>能带收窄</strong>与 <strong>K 点出现能隙</strong>（相对弛豫模型）；模拟提示方法可推广到<strong>含氮—空位色心的金刚石</strong>与<strong>非晶碳</strong>。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>materials</code>）： <ol><li><strong>「先解决最难的观测对象（轻元素），其余观察对象自然被覆盖」</strong>——判据：<strong>当某类成像长期只能看清『重原子』时，把攻关点放在『最轻原子 + 最高精度』上</strong>，一旦突破即同时解锁金刚石色心、非晶碳等一大家族。</li><li><strong>「把结构与物性直接对接」</strong>——实验重建的原子结构喂给 DFT，立即给出能带/能隙预测；判据：<strong>做原子级成像时，把『能否直接算出物性』当作重建质量的外部检验</strong>（呼应母题「<strong>外部信号 &gt; 自评分</strong>」）。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-04-物理-·-2-2-时空的因果结构从学习智能体的记忆里「长」出来" tabindex="-1">科学日报 2026-11-04（物理 · 2/2）：时空的因果结构从学习智能体的记忆里「长」出来 <a class="header-anchor" href="#科学日报-2026-11-04-物理-·-2-2-时空的因果结构从学习智能体的记忆里「长」出来" aria-label="Permalink to &quot;科学日报 2026-11-04（物理 · 2/2）：时空的因果结构从学习智能体的记忆里「长」出来&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-04.md</code> ｜ arXiv: 2611.03596 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：<strong>时空的因果结构</strong>通常被当作先验给定；能否让一个<strong>学习智能体</strong>在<strong>只做量子信息任务、不给它任何度规/因果信息</strong>的条件下，<strong>自己重建出闵可夫斯基时空的因果结构</strong>？</li><li>方法：训练一个<strong>基于模型的强化学习智能体</strong>，去最大化<strong>局域量子探针</strong>与<strong>闵可夫斯基时空中量子场</strong>之间的<strong>量子互信息</strong>；不向它提供<strong>时空度规或因果结构</strong>。</li><li>结果（实测/文中主张）： <ul><li>智能体为完成任务构建的<strong>内部预测模型</strong>，其<strong>规划器自发发展出时空的特征零结构（null structure）</strong>；</li><li>据此可<strong>高精度重建闵可夫斯基度规的因果结构</strong>——时空几何<strong>由智能体的成功预测与动作获得</strong>。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>quantum-physics</code> × <code>ai-brain</code>）： <ol><li><strong>「操作主义视角：几何是被『预测成功』逼出来的，而不是给定的」</strong>——判据：<strong>当追问某结构『为何是它』时，先问『什么样的任务会让它成为最优预测的副产物』</strong>（呼应母题「<strong>约束-涌现</strong>」：给任务约束，几何自己涌现）。</li><li><strong>「互信息当训练信号」</strong>——用<strong>信息量目标</strong>替代显式监督，让结构（此处是因果结构）成为<strong>信息最大化的副产品</strong>；与 <code>topics/physics/science-daily-2026-10-30-physics.md</code> 一类「把物理量写成可优化目标」的做法同族。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ <code>topics/materials/index.md</code> ｜ <code>topics/quantum-physics/index.md</code> ｜ 第54期 科学板块</p></blockquote><p>关键词：科学日报第54期、三维成像单个碳原子、叠层原子电子断层成像pAET、ptychographic atomic electron tomography、扭转双层石墨烯、莫尔体系、0.12埃精度、6648个碳原子、依赖堆叠的层间距、meron反斯格明子手性晶格畸变、DFT能带收窄K点能隙、含氮空位色心金刚石、非晶碳、学习智能体记忆中涌现时空、Spacetime Emergence、量子互信息、闵可夫斯基时空、因果结构重建、零结构null structure、基于模型的强化学习、操作性量子经验、改路径优于加力度、外部信号大于自评分、约束涌现、把物理量写成可优化目标</p><p>关联：<code>topics/physics/index.md</code>、<code>topics/physics/science-daily-2026-11-03-physics.md</code>、<code>topics/physics/science-daily-2026-10-30-physics.md</code>、<code>topics/materials/index.md</code>、<code>topics/quantum-physics/index.md</code>、<code>topics/ai-system-architecture/index.md</code>、<code>ScienceDaily/daily/2026-11-04.md</code></p>',14)])])}const u=s(r,[["render",n]]);export{h as __pageData,u as default};
